# Fala, Transcrição e IA — lote L15
Q = []
TAILS=[" Essa seria a posição predominante na literatura técnica da área.",
 " Trata-se de entendimento consolidado na literatura técnica contemporânea.",
 " Tal conclusão decorreria, segundo esse entendimento, das características da tecnologia descrita.",
 " Essa seria a leitura mais aceita entre os estudiosos do tema."]
SHORT=[" Isso é consenso na área."," Essa é a regra geral."," Trata-se de prática corrente."," Esse é o entendimento usual."]
def tail(E,C,i):
    gap=len(C)-len(E)
    if len(E) < 0.97*len(C) and gap > 60: return E+TAILS[i%len(TAILS)]
    if len(E) < 0.92*len(C) and gap > 14: return E+SHORT[i%len(SHORT)]
    return E
FD={"tipo":"doutrina","ref":"literatura técnica de ASR e IA; LGPD; Lei 9.610/1998","versao":"conhecimento do autor","conferida":"conhecimento"}
FJ={"tipo":"jurisprudencia","ref":"jurisprudência","versao":"conhecimento do autor","conferida":"conhecimento"}
def P(ponto, arts, padC, padE, dif, C, E, com, terro, tag, jur=False, lei=False):
    ex = {}
    if lei: ex["fonte"]={"tipo":"lei","ref":"Lei 13.709/2018; Lei 9.610/1998","versao":"vigente","conferida":"conhecimento"}
    elif jur: ex["fonte"]=FJ; ex["risco"]=["jurisprudencia_conhecimento"]
    else: ex["fonte"]=FD; ex["risco"]=["doutrina_conhecimento"]
    E = tail(E, C, len(Q))
    padC = padE if padC == 'conceito_correto' else padC
    Q.append((ponto, arts, "C", padC, dif, C, com, "", tag, ex))
    Q.append((ponto, arts, "E", padE, dif, E, com, terro, tag, ex))
_n={}
def G(i,padE,dif,C,E,com,terro,lei=False):
    _n[i]=_n.get(i,0)+1
    P(f"F{i:02d}",[str(i)],"conceito_correto",padE,dif,C,E,com,terro,f"f{i:02d}{_n[i]}",lei=lei)
# ---- 1 pipeline
G(1,"confusao_instituto",2,"No pipeline híbrido clássico de reconhecimento de fala, o modelo acústico estima a probabilidade de unidades sonoras a partir do áudio, o léxico relaciona palavras a sequências de fonemas e o modelo de linguagem estima a probabilidade de sequências de palavras.","No pipeline híbrido clássico de reconhecimento de fala, o modelo de linguagem estima a probabilidade de unidades sonoras a partir do áudio, o modelo acústico relaciona palavras a sequências de fonemas e o léxico estima a probabilidade de sequências de palavras.","Modelo acústico, léxico e modelo de linguagem.","troca funções dos componentes")
G(1,"troca_numero",3,"A taxa de erro de palavras (WER) é calculada pela soma de substituições, inserções e remoções dividida pelo número de palavras da transcrição de referência, de modo que pode ultrapassar cem por cento.","A taxa de erro de palavras (WER) é calculada pela soma de substituições e remoções dividida pelo número de palavras da hipótese gerada pelo sistema, de modo que nunca pode ultrapassar cem por cento.","WER.","omite inserções e troca denominador")
G(1,"excecao_omitida",3,"No pipeline híbrido clássico, uma palavra ausente do vocabulário do sistema (fora do vocabulário, OOV) não pode ser reconhecida como tal, o que prejudica a transcrição de nomes próprios e termos técnicos novos.","No pipeline híbrido clássico, uma palavra ausente do vocabulário do sistema (fora do vocabulário, OOV) é reconhecida normalmente, pois o modelo acústico dispensa o léxico.","OOV.","nega limitação do vocabulário fechado")
G(1,"confusao_instituto",2,"Antes do reconhecimento, o sinal de áudio é convertido em características acústicas, como espectrogramas na escala mel ou MFCCs, calculadas em janelas curtas da ordem de dezenas de milissegundos.","Antes do reconhecimento, o sinal de áudio é convertido em texto fonético, e as características acústicas, como os espectrogramas, são calculadas apenas depois da geração do texto final.","Extração de características.","inverte etapas")
G(1,"excecao_omitida",3,"A taxa de erro de caracteres (CER) é métrica complementar ao WER, útil em línguas sem separação clara entre palavras e em avaliações mais granulares.","A taxa de erro de caracteres (CER) é métrica exclusiva de línguas ocidentais e não pode ser usada em conjunto com o WER.","CER.","restringe CER")
G(1,"excecao_omitida",3,"Um sistema de ASR treinado em fala de uso geral tende a apresentar mais erros em vocabulário técnico e em nomes próprios de um domínio específico, como o parlamentar, do que em fala corrente.","Um sistema de ASR treinado em fala de uso geral apresenta, necessariamente, o mesmo desempenho em fala corrente e em vocabulário técnico de um domínio específico.","Domínio.","nega dependência de domínio")
# ---- 2 end-to-end
G(2,"confusao_instituto",3,"No CTC (Connectionist Temporal Classification), usa-se um símbolo especial em branco para permitir o alinhamento implícito entre quadros de áudio e rótulos, sem necessidade de alinhamento prévio.","No CTC (Connectionist Temporal Classification), é indispensável o alinhamento manual prévio entre cada quadro de áudio e cada rótulo, e não existe símbolo especial em branco.","CTC.","exige alinhamento manual")
G(2,"excecao_omitida",4,"O CTC assume independência condicional entre as saídas em cada quadro, razão pela qual costuma ser combinado com um modelo de linguagem externo para melhorar a fluência do texto.","O CTC modela explicitamente a dependência entre saídas sucessivas por meio de uma rede de predição interna, razão pela qual dispensa qualquer modelo de linguagem.","CTC e independência condicional.","atribui ao CTC a rede de predição do RNN-T")
G(2,"confusao_instituto",3,"O RNN-T (transducer) combina codificador acústico, rede de predição e rede de junção e emite tokens de forma incremental, o que o torna adequado à transcrição em tempo real.","O RNN-T (transducer) depende do áudio completo antes de emitir qualquer token, o que o torna inadequado à transcrição em tempo real.","RNN-T.","inverte adequação ao streaming")
G(2,"excecao_omitida",3,"Os modelos end-to-end mapeiam o áudio diretamente para texto, em geral em caracteres ou subpalavras, dispensando léxico de pronúncia e componentes treinados separadamente.","Os modelos end-to-end exigem léxico de pronúncia e treinamento separado dos componentes acústico e de linguagem, como no pipeline híbrido.","End-to-end.","mantém componentes do híbrido")
G(2,"confusao_instituto",4,"O wav2vec 2.0 é um modelo de pré-treinamento auto-supervisionado em áudio sem rótulos, que depois pode ser ajustado com quantidade menor de dados transcritos.","O wav2vec 2.0 é um modelo exclusivamente supervisionado, que só pode ser treinado com grande volume de áudio transcrito, sem uso de áudio sem rótulos.","wav2vec 2.0.","nega pré-treinamento auto-supervisionado")
G(2,"excecao_omitida",3,"Modelos codificador-decodificador com atenção geram texto de forma autorregressiva, atendendo a toda a sequência de áudio, e tendem a ser mais naturais para processamento em lote do que para streaming.","Modelos codificador-decodificador com atenção sobre toda a sequência de áudio são, por construção, os mais adequados ao streaming de baixa latência.","Atenção e streaming.","inverte adequação")
# ---- 3 multimodal vs cascata
G(3,"excecao_omitida",3,"No pipeline em cascata, a transcrição intermediária pode ser auditada e revisada por pessoas antes de ser processada por um LLM, o que favorece a rastreabilidade, e somente com ela é possível conferir palavra por palavra o que o ASR entendeu.","No pipeline em cascata, a transcrição intermediária não existe, pois o LLM processa diretamente o áudio, o que impede qualquer auditoria.","Cascata.","atribui ao pipeline a característica do modelo nativo")
G(3,"excecao_omitida",3,"No pipeline em cascata, erros do ASR propagam-se ao LLM, e informações paralinguísticas, como entonação e emoção, tendem a ser perdidas na conversão do áudio em texto.","No pipeline em cascata, os erros do ASR são automaticamente corrigidos pelo LLM, e as informações paralinguísticas são integralmente preservadas no texto.","Propagação de erros.","afirma correção automática")
G(3,"confusao_instituto",3,"LLMs multimodais de áudio nativo recebem o áudio como entrada, sem etapa explícita de transcrição, e podem aproveitar informações como prosódia e ruído ambiente.","LLMs multimodais de áudio nativo exigem sempre uma transcrição prévia por modelo de ASR e só processam texto, razão pela qual ignoram a prosódia.","Áudio nativo.","nega processamento direto do áudio")
G(3,"excecao_omitida",4,"Em contextos que exigem rastreabilidade, como registros parlamentares, a existência de uma transcrição intermediária revisável é vantagem relevante do pipeline em cascata em relação ao uso direto de um modelo de áudio nativo.","Em contextos que exigem rastreabilidade, como registros parlamentares, a ausência de transcrição intermediária é vantagem do modelo de áudio nativo, pois elimina o risco de alucinação.","Rastreabilidade.","afirma que áudio nativo elimina alucinação")
G(3,"caso_concreto",4,"Um órgão que precisa de um registro de sessão com possibilidade de conferência palavra por palavra pode optar por manter a transcrição como produto intermediário, ainda que utilize um LLM para tarefas auxiliares, como resumo.","Um órgão que precisa de um registro de sessão com possibilidade de conferência palavra por palavra deve preferir um modelo de áudio nativo que entregue apenas o resumo, dispensando o texto da transcrição.","Escolha de arquitetura.","inverte critério de rastreabilidade")
G(3,"excecao_omitida",3,"Modelos de áudio nativo não oferecem, por si, garantia de ausência de alucinação sobre o conteúdo do áudio, e o custo computacional pode ser maior do que o de um pipeline especializado.","Modelos de áudio nativo garantem a ausência de alucinação sobre o conteúdo do áudio, e seu custo computacional é sempre menor do que o de um pipeline especializado.","Limites do áudio nativo.","afirma garantia e custo menor")
# ---- 4 diarização
G(4,"confusao_instituto",2,"A diarização de falantes segmenta o áudio e agrupa os trechos por falante, rotulando-os de forma anônima, sem necessariamente identificar quem é cada pessoa.","A diarização de falantes identifica necessariamente o nome civil de cada orador, a partir da análise da voz, sem necessidade de cadastro prévio.","Diarização.","atribui identificação nominal")
G(4,"confusao_instituto",3,"A identificação de falante associa a voz a uma identidade conhecida, a partir de perfis previamente cadastrados, e é distinta da diarização.","A identificação de falante e a diarização são sinônimos, pois ambas atribuem automaticamente o nome real da pessoa sem cadastro prévio.","Identificação x diarização.","iguala os conceitos")
G(4,"troca_numero",4,"A taxa de erro de diarização (DER) soma a fala não detectada, o falso alarme e a confusão de falantes.","A taxa de erro de diarização (DER) soma apenas os erros de palavra (substituições, inserções e remoções), como o WER.","DER.","confunde DER com WER")
